odifier.height(28.dp)); Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) { Text("Produk terbaru", style = MaterialTheme.typography.titleLarge, modifier = Modifier.weight(1f)); Text("Lihat semua", style = MaterialTheme.typography.labelLarge, color = RematerialColors.DeepForest, modifier = Modifier.clickable(onClick = onProducts).padding(8.dp)) }; state.listings.take(2).forEach { listing -> Row(Modifier.fillMaxWidth().padding(vertical = 12.dp), verticalAlignment = Alignment.CenterVertically) { listing.imageRes?.let { Image(painterResource(it), listing.title, Modifier.size(50.dp).clip(RoundedCornerShape(8.dp)), contentScale = androidx.compose.ui.layout.ContentScale.Crop) }; Spacer(Modifier.width(12.dp)); Column(Modifier.weight(1f)) { Text(listing.title, style = MaterialTheme.typography.titleMedium); Text("${listing.stock} stok · ${if (listing.published) "Tayang" else "Diarsipkan"}", style = MaterialTheme.typography.bodySmall, color = RematerialColors.Muted) }; Text(rupiah(listing.price), style = MaterialTheme.typography.bodySmall, color = RematerialColors.DeepForest) } } } }

